    public LruCache(int capacity) {
        if (capacity <= 0) {
            throw new IllegalArgumentException("capacity must be > 0");
        }

        this.capacity = capacity;
        this.store = new LinkedHashMap<>(16, 0.75f, true) {
            @Override
